package com.supportsphere.service; import com.supportsphere.model.*; import java.time.*; import java.util.*; public class MatchingService {public record VolunteerMatch(Volunteer volunteer,int score,List<String> reasons){} public List<VolunteerMatch> rank(AssistanceRequest r,List<Volunteer> vs){List<VolunteerMatch>x=new ArrayList<>();for(Volunteer v:vs){List<String> reasons=new ArrayList<>();int score=0;boolean skill=v.getSkills().stream().anyMatch(s->s.equalsIgnoreCase(r.getTaskType()));if(skill){score+=40;reasons.add("Skill match");}else continue; if(eq(v.getArea(),r.getArea())&&eq(v.getCity(),r.getCity())){score+=25;reasons.add("Location match");}else if(eq(v.getCity(),r.getCity())){score+=15;reasons.add("City match");}else continue; if(v.getAvailabilityStart()!=null&&v.getAvailabilityEnd()!=null&&!r.getStartTime().isBefore(v.getAvailabilityStart())&&!r.getEndTime().isAfter(v.getAvailabilityEnd())){score+=15;reasons.add("Available for requested time");}else continue;int exp=Math.min(v.getExperienceYears()*2,10);score+=exp;if(exp>0)reasons.add("Experience +"+exp);if(v.getRating()>=4.5){score+=10;reasons.add("Highly rated");}else if(v.getRating()>=4){score+=8;reasons.add("Good rating");}else if(v.getRating()>=3){score+=5;reasons.add("Established rating");}if(v.getVerificationStatus().equals("VERIFIED")){reasons.add("Verified volunteer");}else if(!v.getVerificationStatus().equals("PENDING")){continue;}x.add(new VolunteerMatch(v,Math.min(score,100),reasons));}x.sort(Comparator.comparingInt(VolunteerMatch::score).reversed());return x;}private boolean eq(String a,String b){return a!=null&&b!=null&&a.trim().equalsIgnoreCase(b.trim());}}
